256	   * failed). Callbacks registered after this resolves settle independently;
257	   * during shutdown this is awaited only after the registration window has
258	   * effectively closed.
259	   */
260	  public whenAllCallbacksSettled(): Promise<void> {
261	    if (this.areAllCallbacksSettled()) {
262	      return Promise.resolve();
263	    }
264	    return new Promise<void>(resolve => this.settledWaiters.push(resolve));
265	  }
266	
267	  private areAllCallbacksSettled(): boolean {
268	    return this.callbacks.every(
269	      entry => entry.state === 'completed' || entry.state === 'failed',
270	    );
271	  }
272	
273	  /**
274	   * Freezes the snapshot and schedules the registered callbacks. Idempotent:
275	   * duplicate invocations (finish and close racing, framework quirks,
276	   * shutdown) do not increment the termination count, re-freeze the data or
277	   * run any callback twice.
278	   */
279	  public terminate(reason: RequestContextTerminationReason): void {
280	    if (this.frozen) {
281	      return;
282	    }
283	
284	    this.terminationCount++;
285	    this.terminationReason = reason;
286	    this.terminatedAt = new Date();
287	
288	    // Copy the current metadata into a frozen map: the old map is never read
289	    // again, and dropped `set` calls cannot mutate the frozen copy. The map is
290	    // shallowly immutable; nested values remain application-owned data.
291	    this.data = Object.freeze(
292	      new Map<string, unknown>(this.data as Map<string, unknown>),
293	    );
294	    this.frozen = true;
295	
296	    const waiters = this.frozenWaiters;
297	    this.frozenWaiters = [];
298	    waiters.forEach(resolve => resolve());
299	
300	    for (const entry of this.callbacks) {
301	      this.scheduleCallback(entry);
302	    }
303	    // Recompute in-flight state after scheduling: snapshots without
304	    // callbacks settle immediately and can be released by their host.
305	    this.emitPendingState();
306	  }
307	
308	  /**
309	   * Schedules one callback on the next phase of the event loop, ensuring the
310	   * response has fully finished (including the framework `close` event)
311	   * before post-response work starts. Errors are captured per callback.
312	   */
313	  private scheduleCallback(entry: CallbackEntry): void {
314	    if (entry.state !== 'pending') {
315	      return;
316	    }
317	    entry.state = 'running';
318	    setImmediate(() => {
319	      let result: unknown;
320	      try {
321	        result = entry.callback(this);
322	      } catch (error) {
323	        entry.state = 'failed';
324	        entry.error = error;
325	        this.onCallbackSettled();
326	        return;
327	      }
328	      if (isPromiseLike(result)) {
329	        Promise.resolve(result).then(
330	          () => {
331	            entry.state = 'completed';
332	            this.onCallbackSettled();
333	          },
334	          error => {
335	            entry.state = 'failed';
336	            entry.error = error;
337	            this.onCallbackSettled();
338	          },
339	        );
340	      } else {
341	        entry.state = 'completed';
342	        this.onCallbackSettled();
343	      }
344	    });
345	  }
346	
347	  private onCallbackSettled(): void {
348	    if (this.areAllCallbacksSettled()) {
349	      const waiters = this.settledWaiters.splice(0);
350	      waiters.forEach(resolve => resolve());
351	    }
352	    this.emitPendingState();
353	  }
354	}
355	
356	function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
357	  return (
358	    !!value &&
359	    (typeof value === 'object' || typeof value === 'function') &&
360	    typeof (value as PromiseLike<unknown>).then === 'function'
361	  );
362	}
