2	import {
3	  FastifyAdapter,
4	  NestFastifyApplication,
5	} from '@nestjs/platform-fastify';
6	import * as http from 'node:http';
7	import { AppModule } from '../src/app.module.js';
8	import { ContextRecordsStore } from '../src/context-records.store.js';
9	import { getPort, rawGet, recordById, waitForRecords } from './harness.js';
10	
11	describe('Request context snapshots (Fastify adapter)', () => {
12	  let app: NestFastifyApplication;
13	  let port: number;
14	
15	  beforeEach(async () => {
16	    app = await NestFactory.create<NestFastifyApplication>(
17	      AppModule,
18	      new FastifyAdapter(),
19	      { logger: false },
20	    );
21	    port = await getPort(app);
22	  });
23	
24	  afterEach(async () => {
25	    await app?.close();
26	  });
27	
28	  it('runs the post-response callback with the frozen marker and terminates once', async () => {
29	    const probe = await rawGet(port, '/context-probe?marker=fastify-m1');
30	    expect(probe.statusCode).toBe(200);
31	    const [callbackId] = probe.body.callbackIds;
32	
33	    const frozen = await waitForRecords(port, records =>
34	      records.some(
35	        record =>
36	          record.callbackId === callbackId && record.status === 'frozen',
37	      ),
38	    );
39	    expect(recordById(frozen, callbackId).terminationReason).toBe('finish');
40	
41	    await rawGet(port, '/release-gates');
42	    const records = await waitForRecords(port, items =>
43	      items.some(
44	        record =>
45	          record.callbackId === callbackId &&
46	          record.status === 'completed' &&
47	          record.repeatedReadsConsistent === true &&
48	          record.lateWriteAccepted === false,
49	      ),
50	    );
51	    expect(recordById(records, callbackId).frozenMarker).toBe('fastify-m1');
52	  });
53	
54	  it('isolates concurrent requests with different markers', async () => {
55	    const markers = ['one', 'two', 'three'];
56	    const probes = await Promise.all(
57	      markers.map(marker =>
58	        rawGet(port, `/context-probe?marker=${marker}&consumerValue=${marker}`),
59	      ),
60	    );
61	    const idToMarker = new Map<string, string>();
62	    probes.forEach((probe, index) =>
63	      idToMarker.set(probe.body.callbackIds[0], markers[index]),
64	    );
65	
66	    await rawGet(port, '/release-gates');
67	    const records = await waitForRecords(
68	      port,
69	      items => items.length === 3 && items.every(r => r.status === 'completed'),
70	    );
71	    for (const record of records) {
72	      const marker = idToMarker.get(record.callbackId);
73	      expect(record.frozenMarker).toBe(marker);
74	      expect(record.consumerValue).toBe(marker);
75	      expect(record.terminationCount).toBe(1);
76	    }
77	  });
78	
79	  it('terminates snapshots for default and custom-filter error responses', async () => {
80	    const defaultError = await rawGet(
81	      port,
82	      '/context-probe?marker=ferr0&fail=request',
83	    );
84	    expect(defaultError.statusCode).toBe(400);
85	
86	    const filtered = await rawGet(
87	      port,
88	      '/context-probe?marker=ferr&fail=filtered',
89	    );
90	    expect(filtered.statusCode).toBe(422);
91	    expect(filtered.body).toEqual({ filtered: true, marker: 'ferr' });
92	
93	    await rawGet(port, '/release-gates');
94	    const records = await waitForRecords(
95	      port,
96	      items => items.length === 2 && items.every(r => r.status === 'completed'),
97	    );
98	    expect(records.map(r => r.terminationReason)).toEqual(['finish', 'finish']);
99	    expect(records.map(r => r.terminationCount)).toEqual([1, 1]);
100	    expect(records.map(r => r.frozenMarker)).toEqual(['ferr0', 'ferr']);
101	  });
102	
103	  it('terminates the snapshot when the client aborts', async () => {
104	    const probe = rawGet(port, '/context-probe?marker=fabort&delayMs=3000');
105	    probe.catch(() => {});
106	    setTimeout(() => probe.req!.destroy(), 80);
107	
108	    const records = await waitForRecords(port, items =>
109	      items.some(
110	        record =>
111	          record.marker === 'fabort' &&
112	          record.status === 'frozen' &&
113	          record.terminationReason === 'abort',
114	      ),
115	    );
116	    const callbackId = records.find(r => r.marker === 'fabort')!.callbackId;
117	
118	    await rawGet(port, '/release-gates');
119	    const settled = await waitForRecords(port, items =>
120	      items.some(
121	        record =>
122	          record.callbackId === callbackId && record.status === 'completed',
123	      ),
124	    );
125	    expect(recordById(settled, callbackId)).toMatchObject({
126	      terminationReason: 'abort',
127	      terminationCount: 1,
128	      frozenMarker: 'fabort',
129	    });
130	  }, 10_000);
131	
132	  it('drains parked callbacks during shutdown and then refuses new requests', async () => {
133	    const probe = await rawGet(port, '/context-probe?marker=fshutdown');
134	    await waitForRecords(port, records =>
135	      records.some(
136	        record =>
137	          record.callbackId === probe.body.callbackIds[0] &&
138	          record.status === 'frozen',
139	      ),
140	    );
141	
142	    await app.close();
143	
144	    const store = app.get(ContextRecordsStore);
145	    const [record] = store.getAll();
146	    expect(record).toMatchObject({
147	      marker: 'fshutdown',
148	      frozenMarker: 'fshutdown',
149	      status: 'completed',
150	    });
151	
152	    await expect(
153	      new Promise((resolve, reject) =>
154	        http.get({ port, path: '/health' }, resolve).on('error', reject),
155	      ),
156	    ).rejects.toMatchObject({ code: 'ECONNREFUSED' });
157	  }, 15_000);
158	});
