101	export class ExpressAdapter extends AbstractHttpAdapter<
102	  http.Server | https.Server
103	> {
104	  private readonly routerMethodFactory = new RouterMethodFactory();
105	  private readonly logger = new Logger(ExpressAdapter.name);
106	  private readonly openConnections = new Set<Duplex>();
107	  private readonly registeredPrefixes = new Set<string>();
108	  private isShuttingDown = false;
109	  private onRequestHook?: (
110	    req: express.Request,
111	    res: express.Response,
112	    done: () => void,
113	  ) => Promise<void> | void;
114	  private onResponseHook?: (
115	    req: express.Request,
116	    res: express.Response,
117	  ) => Promise<void> | void;
118	  private customVersioningFilterCache?: {
119	    routerStackSize: number;
120	    versionsByFilter: WeakMap<Function, ReadonlySet<string>>;
121	  };
122	
123	  constructor(instance?: any) {
124	    super(instance || express());
125	    this.instance!.use((req, res, next) => {
126	      if (this.onResponseHook) {
127	        res.on('finish', () => {
