9	/**
10	 * Request-scoped probe controller. Every request gets a fresh controller
11	 * instance, hence a fresh request-scoped context and fresh transient probes,
12	 * while the singleton probe is shared for the whole application lifetime.
13	 */
14	@Controller({ path: 'scope-probe', scope: Scope.REQUEST })
15	export class ScopeProbeController {
16	  constructor(
17	    private readonly requestContext: RequestContextService,
18	    private readonly transientProbe: TransientProbeService,
19	    private readonly singletonProbe: SingletonProbeService,
20	    private readonly transientConsumer: TransientConsumerService,
21	    private readonly business: ProbeBusinessService,
22	  ) {}
23	
24	  @Get()
25	  probe(@Query('marker') marker = '') {
26	    // The same consumer observes the same transient instance every time it
27	    // reads it; a different consumer receives a distinguishable instance.
28	    const firstTransientRead = this.transientProbe.id;
29	    const secondTransientRead = this.transientProbe.id;
30	
31	    return {
32	      marker,
33	      requestId: this.requestContext.id,
34	      transientId: firstTransientRead,
35	      singletonId: this.singletonProbe.id,
36	      sameConsumerTransientEqual: firstTransientRead === secondTransientRead,
37	      crossConsumerTransientEqual:
38	        firstTransientRead === this.transientConsumer.transientProbe.id,
39	      businessValue: this.business.getBusinessValue(marker),
40	      cleanup: ProbeCleanupStore.snapshot(),
41	    };
