import { Controller, Get, Inject, Query, Scope } from '@nestjs/common';
import { REQUEST_CONTEXT, type RequestContextSnapshot } from '@nestjs/core';

/**
 * Request-scoped controller exercising the {@link REQUEST_CONTEXT} injection
 * token exported by `RequestContextModule` (the DI counterpart of the
 * `@RequestContext()` parameter decorator).
 */
@Controller({ scope: Scope.REQUEST })
export class ContextEchoController {
  constructor(
    @Inject(REQUEST_CONTEXT)
    private readonly context: RequestContextSnapshot | undefined,
  ) {}

  @Get('context-echo')
  public echo(@Query('value') value?: string) {
    if (!this.context) {
      return { attached: false as const };
    }
    if (value !== undefined) {
      this.context.set('echoValue', value);
    }
    return {
      attached: true as const,
      contextId: this.context.id,
      frozen: this.context.isFrozen(),
      echoValue: this.context.get<string>('echoValue') ?? null,
    };
  }
}

import { APP_FILTER, Module } from '@nestjs/common';
import { RequestContextModule } from '@nestjs/core';
import { AsyncContextController } from './async-context.controller.js';
import { ContextEchoController } from './context-echo.controller.js';
import { AsyncRecordsController } from '../shared/async-records.controller.js';
import { AsyncRecordsStore } from '../shared/async-records.store.js';
import { ProbeExceptionFilter } from '../shared/probe-exception.filter.js';
import { SingletonProbeService } from '../shared/singleton-probe.service.js';

/**
 * Application that registers `RequestContextModule.forRoot()`. Bootstrapped
 * once with Express and once with Fastify by the e2e specs.
 */
@Module({
  imports: [RequestContextModule.forRoot()],
  controllers: [
    AsyncContextController,
    AsyncRecordsController,
    ContextEchoController,
  ],
  providers:
    // Registration order is flipped in a second variant by the specs via
    // ContextAppModule.withReversedRegistrationOrder().
    [
      AsyncRecordsStore,
      SingletonProbeService,
      {
        provide: APP_FILTER,
        useClass: ProbeExceptionFilter,
      },
    ],
})
export class ContextAppModule {
  /**
   * Builds an equivalent module description with module/controller/provider
   * registration order reversed, used to prove order-independence.
   */
  public static withReversedRegistrationOrder() {
    return {
      module: ContextAppModule,
      imports: [RequestContextModule.forRoot()],
      controllers: [
        ContextEchoController,
        AsyncRecordsController,
        AsyncContextController,
      ],
      providers: [
        {
          provide: APP_FILTER,
          useClass: ProbeExceptionFilter,
        },
        SingletonProbeService,
        AsyncRecordsStore,
      ],
    };
  }
}

