@Module({ providers: [FailingLifecycle] })
class BadModule {}

it('listen failure closes server', async () => {
  const app = await NestFactory.create(BadModule, { logger: false, abortOnError: false });
  let port = 0;
  await expect(app.listen(0)).rejects.toThrow('boom lifecycle');
  const server: http.Server = app.getHttpServer();
  const addr = server.address();
  console.log('address after failure:', addr);
  if (addr && typeof addr === 'object') port = addr.port;
  if (port) {
    const refused = await new Promise<boolean>(resolve => {
      http.get({ port, path: '/' }, res => { res.resume(); resolve(false); })
        .on('error', e => resolve((e as NodeJS.ErrnoException).code === 'ECONNREFUSED'));
    });
    console.log('connection refused:', refused);
  }
  await app.close();
}, 30000);
