1	import { Injectable, OnModuleDestroy } from '@nestjs/common';
2	import { randomUUID } from 'crypto';
3	
4	/**
5	 * Lifecycle of a single post-response continuation, as observed through
6	 * `/async-records`:
7	 *
8	 * - `pending`   - the continuation was registered and has not produced its
9	 *                 result yet (either the request is still in flight or the
10	 *                 continuation is parked behind its gate).
11	 * - `completed` - the continuation read the frozen snapshot successfully.
12	 * - `failed`    - the continuation threw or rejected; the error was captured.
13	 *
14	 * A settled record is reported forever as `completed`/`failed`: it can never
15	 * go back to `pending`.
16	 */
17	export type ContinuationStatus = 'pending' | 'completed' | 'failed';
18	
19	export interface ContinuationRecord {
20	  id: string;
21	  contextId: string;
22	  marker: string;
23	  status: ContinuationStatus;
24	  frozenValue: string | null;
25	  frozenValueStable: boolean | null;
26	  lateWriteAccepted: boolean | null;
27	  errorMessage: string | null;
28	  registeredAt: number;
29	}
30	
31	interface Gate {
32	  promise: Promise<void>;
33	  release: () => void;
34	}
35	
36	function createGate(): Gate {
37	  let release: () => void = () => {};
38	  const promise = new Promise<void>(resolve => {
39	    release = resolve;
40	  });
41	  return { promise, release };
42	}
43	
44	/**
45	 * Application-scoped, in-memory store of continuation records. It is a
46	 * regular singleton provider, so every bootstrapped application gets an
47	 * independent store: recreating the application can never replay or inherit
48	 * records, and two applications coexisting in one process cannot see each
49	 * other's data.
50	 */
51	@Injectable()
52	export class AsyncRecordsStore implements OnModuleDestroy {
53	  private readonly records = new Map<string, ContinuationRecord>();
54	  private readonly order: string[] = [];
55	  private readonly gates = new Map<string, Gate>();
56	
57	  /**
58	   * Opens a record for a continuation that was just registered. The record
59	   * starts as `pending`. Every continuation gets its own record - even
60	   * continuations carrying identical markers or running in the same request.
61	   */
62	  public register(contextId: string, marker: string): string {
63	    const id = randomUUID();
64	    const record: ContinuationRecord = {
65	      id,
66	      contextId,
67	      marker,
68	      status: 'pending',
69	      frozenValue: null,
70	      frozenValueStable: null,
71	      lateWriteAccepted: null,
72	      errorMessage: null,
73	      // Tie-break so insertion ordering is total even within one tick.
74	      registeredAt: Date.now() + this.order.length / 1000,
75	    };
76	    this.records.set(id, record);
77	    this.order.push(id);
78	    this.gates.set(id, createGate());
79	    return id;
80	  }
81	
82	  /**
83	   * Parks the continuation until a test releases its gate (or shutdown
84	   * releases every gate). This makes the `pending` state deterministic to
85	   * observe from `/async-records`.
86	   */
87	  public waitForGate(id: string): Promise<void> {
88	    return this.gates.get(id)?.promise ?? Promise.resolve();
89	  }
90	
91	  public releaseGate(id: string): void {
92	    this.gates.get(id)?.release();
93	  }
94	
95	  public releaseAllGates(): void {
96	    this.gates.forEach(gate => gate.release());
97	  }
98	
99	  public markCompleted(
100	    id: string,
101	    payload: Pick<ContinuationRecord, 'frozenValue' | 'frozenValueStable'> & {
102	      lateWriteAccepted: boolean;
103	    },
104	  ): void {
105	    const record = this.records.get(id);
106	    if (!record || record.status !== 'pending') {
107	      // A settled record is immutable: a late settlement can never rewrite a
108	      // completed or failed record.
109	      return;
110	    }
111	    Object.assign(record, payload, { status: 'completed' as const });
112	  }
113	
114	  public markFailed(id: string, error: unknown): void {
115	    const record = this.records.get(id);
116	    if (!record || record.status !== 'pending') {
117	      return;
118	    }
119	    record.status = 'failed';
120	    record.errorMessage =
121	      error instanceof Error ? error.message : String(error);
122	  }
123	
124	  /**
125	   * Safety net for shutdown: never let a parked gate delay application close.
126	   * Runs before the request-context shutdown drain that awaits the now
127	   * unblocked continuations.
128	   */
129	  public onModuleDestroy(): void {
130	    this.releaseAllGates();
131	  }
132	
133	  public getAll(): ContinuationRecord[] {
134	    return this.order.map(id => this.records.get(id)!);
135	  }
136	}

